const fs=require('node:fs'),path=require('node:path'),os=require('node:os');
(async()=>{const dirs=fs.readdirSync(os.tmpdir()).filter(x=>x.startsWith('alumni-voices-')).map(x=>path.join(os.tmpdir(),x)).sort((a,b)=>fs.statSync(b).birthtimeMs-fs.statSync(a).birthtimeMs);const port=fs.readFileSync(path.join(dirs[0],'DevToolsActivePort'),'utf8').split('\n')[0];const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();console.log(tabs.map(t=>({url:t.url,id:t.id})));const s=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>s.addEventListener('open',r,{once:true}));s.addEventListener('message',e=>{console.log(e.data);s.close();});s.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression:"JSON.stringify({url:location.href,status:document.querySelector('#veStatus')?.textContent,pop:document.querySelector('#vePop')?.innerText,busy:window.VE?.state.busy,discardHidden:document.getElementById('veDiscardDraft')?.hidden,src:document.getElementById('veFrame')?.src,items:window.VE?.adapter().draftState().alumniVoices?.data?.items,dialogs:[...document.querySelectorAll('dialog[open]')].map(d=>d.innerText)})",returnByValue:true,timeout:5000}}));setTimeout(()=>{s.close();},6000);})().catch(console.error);
